<?php require 'config.php';require_login();if(is_admin()){header('Location: admin.php');exit;}$page_title='Shop';$cat=$_GET['category']??'';$sql="SELECT * FROM products WHERE is_active=1";$args=[];if($cat){$sql.=" AND category=?";$args[]=$cat;}$sql.=" ORDER BY id";$s=$pdo->prepare($sql);$s->execute($args);$products=$s->fetchAll();require 'header.php';?>
<section class="wrap"><div class="eyebrow">JLB Collection's</div><h1>Shop all <?=e($cat?:'collections')?></h1><p class="muted">Choose your pieces. Select your size, colour, and preferred design on each product page.</p><p><?php foreach(['T-Shirts','Shorts','Pants','Bags','Accessories','Caps'] as $c):?><a class="btn" style="margin:4px" href="shop.php?category=<?=urlencode($c)?>"><?=e($c)?></a><?php endforeach;?></p><div class="products"><?php foreach($products as $p):?><article class="product"><a href="product.php?id=<?=$p['id']?>"><img src="<?=e($p['image_url'])?>" alt=""><h3><?=e($p['name'])?></h3></a><p class="price"><?=money($p['price'])?></p><p><?=$p['stock']>0?'Stock: '.(int)$p['stock']:'<span class="sold">SOLD OUT</span>'?></p><a class="btn" href="product.php?id=<?=$p['id']?>">View item</a></article><?php endforeach;?></div></section><?php require 'footer.php';?>
